// 5.3 / 1.1.0: player settings. Written like the Builder (D3): a hidden user message carrying an MVU patch, so swipes/deletes stay consistent.
// 1.1.0 (spec §9): Features: one row per toggleable feature with its token estimate; turning one off parks its state (engine §0b).
const FEATS = (DATA.features || []), FCOST = DATA.fcost || { rules: {}, live: {}, core_rules: 0, lore: 0 };
const featureLevel = (S, f) => { const u = (S && S.$ui) || {}; return f.control === 'levels' ? (u[f.field] || (f.id === 'weather' ? 'full' : 'normal')) : ((u.off || []).includes(f.id) ? 'off' : 'on'); };
function featureOn(S, id) { const f = FEATS.find(x => x.id === id); return !f || featureLevel(S, f) !== 'off'; }
const omit$ = o => (Array.isArray(o) ? o.map(omit$) : o && typeof o === 'object' ? Object.fromEntries(Object.entries(o).filter(([k]) => !k.startsWith('$')).map(([k, v]) => [k, omit$(v)])) : o);
function ylen(v, ind = 0) {         // length of the YAML Tavern Helper prints for <current_state> (close enough for an estimate)
  if (Array.isArray(v)) return v.reduce((a, x) => a + ind + 2 + (x && typeof x === 'object' ? 1 + ylen(x, ind + 2) : String(x).length + 1), 0) || 3;
  if (v && typeof v === 'object') return Object.entries(v).reduce((a, [k, x]) => a + ind + k.length + 2 + (x && typeof x === 'object' ? 1 + ylen(x, ind + 2) : String(x).length + 1), 0) || 3;
  return String(v).length + 1;
}
const tokOf = v => Math.round(ylen(omit$(v)) / 3.6);
function featureState(S, f) {         // live state tokens of a feature (parked state when it is off: what it would cost)
  const u = (S.$ui || {}), on = featureLevel(S, f) !== 'off';
  let n = (f.paths || []).reduce((a, p) => a + tokOf(on ? _.get(S, p) : _.get(u.parked || {}, [f.id, p])), 0);
  if (f.id === 'weather' && on) n += Math.round(((S.World._Weather || '').length + 12) / 3.6) + FCOST.live.weather;
  if (f.id === 'class' && on && /^P[123] /.test(S.World._Period || '')) n += FCOST.live.class;
  if (f.id === 'gossip' && on) n += (u.gossip || []).slice(-5).reduce((a, g) => a + Math.round((String(g[0]).length + 30) / 3.6), 0);
  if (f.id === 'hooks' && on) n += Object.values(S.Hooks || {}).filter(h => /due|overdue/.test(h._State || '')).length * 20;
  if (f.id === 'happenings' && on && S.World._Happening) n += Math.round((S.World._Happening.length + 60) / 3.6);   // _Happening + the Now line
  return n;
}
function featureOps(S, id, v) {
  const f = FEATS.find(x => x.id === id); if (!S || !f) return null;
  if (f.control === 'levels') { if (featureLevel(S, f) === v) return null; return { ops: [{ op: 'replace', path: `/$ui/${f.field}`, value: v }], head: `⚙️ Setting: ${f.name} → ${v}.` }; }
  const off = new Set((S.$ui || {}).off || []); if (v === 'off') off.add(id); else off.delete(id);
  return { ops: [{ op: 'replace', path: '/$ui/off', value: [...off] }], head: `⚙️ Setting: ${f.name} → ${v}.` };
}
function pSettings(S) {
  const J = (S.Journal || []).length, A = ((S.$ui || {}).archive || []).length;
  let on = 0, saved = 0;
  const rows = FEATS.map(f => {
    const lv = featureLevel(S, f), isOn = lv !== 'off', rules = FCOST.rules[f.id] || 0, st = featureState(S, f);
    if (isOn) on += rules + st; else saved += rules + st;
    const ctl = f.control === 'levels' ? f.levels : [['on', 'On'], ['off', 'Off']];
    return `<div class="feat${isOn ? '' : ' off'}"><div class="fm"><b>${esc(f.name)}</b><div class="sub">${esc(f.desc)}</div>
      <div class="sub tk">rules ≈${rules} · state ≈${st}${f.unit && st > 1 ? ` (${esc(f.unit)})` : ''} tokens${isOn ? '' : ' · off: parked, restored when you turn it on'}</div></div>
      <div class="tog">${ctl.map(([v, l]) => `<button data-act="${f.control === 'levels' ? 'featlv' : 'feat'}" data-f="${esc(f.id)}" data-v="${v}" class="${lv === v ? 'on' : ''}" aria-pressed="${lv === v}" ${view.busy ? 'disabled' : ''}>${l}</button>`).join('')}</div></div>`;
  }).join('');
  const featPaths = FEATS.flatMap(f => f.paths || []);
  const core = omit$(S); for (const p of featPaths) _.unset(core, p);
  const coreTok = FCOST.core_rules + tokOf(core), total = coreTok + FCOST.lore + on;
  return `<h3>Features</h3>
  <p class="hint">Turn off what you do not use to keep the prompt short. A feature that is off disappears from the narrator's state and rules, its tabs and chips hide, and whatever it held is kept aside (parked) until you turn it back on. Numbers are estimates (≈3.6 characters per token).</p>
  <div class="feats">${rows}</div>
  <div class="feat core"><div class="fm"><b>Core (always on)</b><div class="sub">Clock and calendar, body, magic, wallet, profile, bonds, journal, campus state, the output format, and the always-on lore (Campus Map, World Index, NPC Roster, Timetable, Calendar). Hidden magic is set by the Builder. The Price Guide is only sent when prices come up (≈${FCOST.price_guide}).</div>
    <div class="sub tk">rules and state ≈${coreTok} · always-on lore ≈${FCOST.lore} tokens</div></div></div>
  <p class="tot">Estimated always-on total for this chat now: <b>≈${total.toLocaleString('en')}</b> tokens${saved ? ` · saved by features that are off: ≈${saved.toLocaleString('en')}` : ''}.</p>
  <p class="hint">The preset and the chat history come on top of this. Changing a setting adds a small hidden note to the chat (it is not sent to the narrator).</p>
  <h3>Story memory</h3>
  <p class="hint">The narrator reads only the latest 24 or so messages; older ones reach it as […]. What it remembers of the rest is the game state: the Journal (${J} of 30 lines; ${A} archived, still shown in your Notebook), bonds, campus news, commitments and clues.
  To change how much chat it reads, edit the Min Depth of the regex "Eldrasil — State-as-memory: trim far chat (prompt)" in the Regex extension; disable that regex to send the whole chat.</p>
  <h3>MVU mode</h3>
  <p class="hint">This card asks MVU to update variables together with the AI's reply (card config override). You can change it in the MVU panel under the current card's config.</p>`;
}
async function commitSetting(ops, head) {
  if (view.busy) return;
  const st = latestState(); if (!st) return;
  view.busy = true; render();
  try {
    const text = `${head}\n<UpdateVariable>\n<Analysis>Player setting (player tool). Not part of the story.</Analysis>\n<JSONPatch>\n${JSON.stringify(ops)}\n</JSONPatch>\n</UpdateVariable>\n\n${PH}`;
    await waitGlobalInitialized('Mvu');
    const next = await Mvu.parseMessage(text, _.cloneDeep(st.data));
    if (!next || !next.stat_data) throw new Error('MVU did not apply the setting.');
    await createChatMessages([{ role: 'user', message: text, is_hidden: true }], { refresh: 'none' });
    const id = getLastMessageId();
    await Mvu.replaceMvuData(next, { type: 'message', message_id: id });
    await setChatMessages([{ message_id: id }], { refresh: 'affected' });
    toastr.success('Setting saved.', 'Eldrasil');
    await eventEmit('eldrasil:state');
  } catch (err) {
    console.error('[Eldrasil UI]', err);
    toastr.error(String(err && err.message || err), 'Eldrasil');
  } finally { view.busy = false; render(); }
}

// 1.1.0 weather glyph for the UI (the bracelet uses Font Awesome icons)
const wxIcon = wx => { const n = wx && wx.now; if (!n) return ''; return n.rare === 'lightning storm' || n.sky === 'Storm' ? '⛈' : n.snow ? '❄' : n.sky === 'Rain' ? '🌧' : n.sky === 'Fog' ? '🌫' : n.sky === 'Overcast' ? '☁' : n.sky === 'Cloudy' ? '⛅' : wx.block === 2 ? '☾' : '☀'; };
const SEASON_OF = m => ['Winter', 'Winter', 'Spring', 'Spring', 'Spring', 'Summer', 'Summer', 'Summer', 'Autumn', 'Autumn', 'Autumn', 'Winter'][((num(m, 1) - 1) % 12 + 12) % 12];

// ---------------------------------------------------------------- shared helpers for Batch 4 panels
const imgURL = path => (DATA.assets && DATA.assets.base ? DATA.assets.base : '') + path;
const npcOf = id => DATA.npcs && DATA.npcs[id];
// D14: the name unlocks at Rank 1, or earlier once the story itself has named them ($ui.names, recorded by the engine)
// ...or when a connection you have learned names them (the note itself says who they are)
const _edgeNames = new WeakMap();
function namedByEdges(S) {
  if (!S || typeof S !== 'object') return new Set();
  if (!_edgeNames.has(S)) _edgeNames.set(S, new Set((DATA.rel || []).filter(e => edgeVisible(e, S) && ((S.Bonds || {})[e[0]])).map(e => e[1])));
  return _edgeNames.get(S);
}
const knowsName = (id, S) => { const b = ((S && S.Bonds) || {})[id]; return !!((b && b.Rank >= 1) || ((S && S.$ui && S.$ui.names) || []).includes(id) || namedByEdges(S).has(id)); };
const nameOf = (id, S, full) => { const n = npcOf(id); if (!n) return id; return knowsName(id, S) ? (full ? n.n : id) : (n.r || n.d); };
const initials = s => String(s).split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase();
function avatar(id, S, cls = 'av') {
  const n = npcOf(id), label = n ? (knowsName(id, S) ? (/\bxs\b/.test(cls) ? id.slice(0, 2) : id) : '?') : initials(id);
  const ring = n ? n.dc : '#6f737b';
  return n ? `<img class="${cls}" style="border-color:${ring}" src="${esc(imgURL(n.t))}" alt="" data-fb="${esc(label)}" data-fbclass="${cls} fb">` : `<span class="${cls} fb" style="border-color:${ring}">${esc(label)}</span>`;
}
const TOPIC = l => { l = l.toLowerCase(); return /magic/.test(l) ? 'magic' : /pact/.test(l) ? 'pact' : /goal/.test(l) ? 'goal' : /backstory|history|family|home/.test(l) ? 'backstory' : /relation/.test(l) ? 'relationship' : 'other'; };
// v1.0.3 (F13): the AI's Secrets_revealed list is capped; $ui.secrets is the engine's permanent ledger. Unlocks read both.
const secretsOf = S => [...new Set([...((S && S.Campus_State && S.Campus_State.Secrets_revealed) || []), ...((S && S.$ui && S.$ui.secrets) || [])])];
// v1.0.3 (F02): Campus_State.NPC_status by NPC id (the engine keys it by first name; full names / other case still match)
const npcStatus = S => { const st = ((S && S.Campus_State) || {}).NPC_status || {}, ks = Object.keys(st);
  return id => { const k = ks.find(x => x === id || x.toLowerCase() === String(id).toLowerCase() || x.toLowerCase().split(/\s+/)[0] === String(id).toLowerCase()); return k ? st[k] : ''; }; };
// v1.0.3: students who left campus after Graduation (Campus_State.Graduated); no longer regulars or club members
const graduated = S => new Set((((S && S.Campus_State) || {}).Graduated) || []);
// v1.0.3 incoming cohorts: an NPC is at Halvard from campaign year DATA.npcs[id].a (1 = from the start) until they graduate
const curYear = S => Math.max(1, num((((S || {}).World) || {}).Year, 1));
const arrived = (id, S) => { const n = npcOf(id); return !n || (n.a || 1) <= curYear(S); };
const atHalvard = (id, S) => arrived(id, S) && !graduated(S).has(id);
const yearNow = (id, S) => { const n = npcOf(id); return n && n.y ? n.y + curYear(S) - (n.a || 1) : 0; };
const revealed = (S, id) => secretsOf(S).filter(x => String(x).split('.')[0].toLowerCase() === id.toLowerCase()).map(x => String(x).split('.').slice(1).join('.').toLowerCase());
function fieldUnlocked(id, f, S) {   // f = [label, text, rank]
  if (f[2] >= 99) { const r = revealed(S, id); return r.includes(TOPIC(f[0])) || r.includes(f[0].toLowerCase()); }
  const b = ((S && S.Bonds) || {})[id];
  return f[2] <= (b ? b.Rank : 0);
}
function edgeVisible(e, S) {         // e = [from, to, type, types, visibility, notes]
  const v = e[4]; if (v === 'public') return true;
  const r = Number(v.split(':')[1]);
  if (r >= 99) return revealed(S, e[0]).includes('relationship');
  const b = ((S && S.Bonds) || {})[e[0]];
  return !!(b && b.Rank >= r);
}
