    ['MESSAGE_RECEIVED', 'MESSAGE_DELETED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED'].forEach(k => tavern_events[k] && eventOn(tavern_events[k], refresh));
    eventOn(tavern_events.CHAT_CHANGED, () => { draft = null; close(); });
